import { MeshStandardNodeMaterial, PlaneGeometry, Mesh, Vector2 } from 'three/webgpu';
import {
  texture,
  uv,
  vec3,
  vec4,
  mix,
  float,
  positionLocal,
  time,
  sin,
  uniform
} from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = 'srgb';

  const ink = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const surface = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);
  const accent = vec3(0xff / 255, 0x2a / 255, 0x38 / 255);

  const vUv = uv();

  // engineered gradient: diagonal blend from surface to ink, with a thin accent seam
  const gradientMix = vUv.x.add(vUv.y).mul(0.5);
  const engineeredGradient = mix(surface, ink, gradientMix);

  // subtle grain via hashed noise from uv + time (static-looking, low amplitude)
  const grainSeed = vUv.x.mul(4173.23).add(vUv.y.mul(917.31));
  const grain = sin(grainSeed.mul(43758.5453)).fract().sub(0.5).mul(0.035);

  const baseColor = texture(map, vUv).rgb;

  const accentSeam = float(1.0).sub(
    vUv.x.sub(0.5).abs().smoothstep(0.0, 0.01)
  ).mul(0.15);

  const finalColor = baseColor
    .mul(0.6)
    .add(engineeredGradient.mul(0.4))
    .add(vec3(grain, grain, grain))
    .add(accent.mul(accentSeam));

  const material = new MeshStandardNodeMaterial();
  material.colorNode = vec4(finalColor, 1.0);
  material.roughnessNode = float(0.55);
  material.metalnessNode = float(0.45);
  material.map = map;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return mesh;
}
